"""Source-reviewed fixed endings from shared link and ticket attendants."""
ROWS = []
def add(key, labels, subject, lines):
    replies = [line.strip() for line in lines.split('|')]
    assert len(replies) == 11, (key, len(replies))
    ROWS.append(dict(key='hoenn_link_' + key, labels=labels.split(), subject=subject, replies=replies))

add('different_choices','Text_PlayersMadeDifferentSelections','A link attendant ends an attempt because the players chose different activities.','''flustered~Our plans took different doors. We should agree on one before trying again.|Matching selections should resolve this particular disagreement.|Pick the same activity. Then try again.|A quick word with everyone would make this less awkward.|It helps to decide together before each person starts.|Our collaboration has encountered the minor flaw of being several different plans.|Togetherness has failed at the menu. A promisingly early warning.|Easy fix: agree on the input before repeating the process.|A shared beginning needs everyone facing the same way.|A little coordination would make the whole arrangement fit better.|I would ask each person what they meant to choose.''')
add('wrong_number','CableClub_Text_IncorrectNumberOfParticipants','A link attendant ends an attempt with the wrong number of participants.','''flustered~The head count did not match the plan. Nobody hide behind anyone this time.|We should check the required group size before reconnecting.|Count everyone. Check what the activity needs.|At least the problem is clear enough to sort out.|We can get the group together before trying to begin.|Our gathering has been defeated by arithmetic at the door.|The company is pleasant, but apparently not numerically acceptable.|The number of participants is a straightforward requirement to verify.|A group can be almost ready and still need one small change.|The right arrangement needs the right number of people.|I would check whether someone joined the wrong group.''')
add('ticket_decline','EventTicket_Text_AsYouLike','A harbor attendant accepts the players decision against the proposed ticket voyage.','''soft_smile~Our sea legs can stay on land a bit longer. Fair enough.|The choice is accepted. We can reconsider when the journey suits us.|No sailing now. We can leave it at that.|It is nice to have a choice accepted without a fuss.|A trip can wait until we actually want to take it.|The proposed voyage has been folded neatly back into possibility.|The sea will survive our temporary lack of commitment.|No need to start a journey without a reason to go.|Staying can be a choice as much as setting out.|A gracious answer to a change of plans.|I would rather choose the trip than feel hurried into it.''')
add('connection_error','Text_LinkErrorPleaseReset','An attendant reports a link error and asks for a reset before another attempt.','''sad~The connection has tied itself in a knot. We should follow the restart instructions.|A clean restart may clear the failed connection state.|Follow the instructions. Do not keep forcing the same attempt.|That is frustrating after getting everyone ready.|A pause to get things working is better than another rushed try.|The grand meeting has been interrupted by a stubbornly uncooperative connection.|Our attempt has become a very brief lesson in patience.|We have a failure report and a recovery step. Start there.|A stopped connection need not spoil the whole visit.|An inconvenient interruption, but at least the next step is clear.|I would make sure everyone heard the same restart instructions.''')
add('someone_not_ready','Text_SomeoneIsNotReadyToLink','An attendant asks the group to return once all participants have prepared.','''soft_smile~One person still needs a moment. Our grand team can practice waiting together.|Readiness has to include every participant before the attempt begins.|Check who needs help. Start when everyone is ready.|I would not want the last person to feel rushed.|A little time now can make the whole shared activity nicer.|Our ensemble has discovered that the opening requires the entire cast.|A very reasonable delay for the unfashionable business of being prepared.|We should compare the preparations rather than repeat the attempt blindly.|The last person matters as much as the first one ready.|A coordinated start looks better than leaving somebody behind.|I would ask quietly whether anyone is stuck on a step.''')
add('eon_ticket_advice','MysteryGift_Text_TryUsingItAtLilycovePort','A gift attendant recommends taking the newly supplied ticket to Lilycove port.','''soft_smile~A ticket with somewhere to ask about it. That is a useful little beginning.|The port is the appropriate place to confirm what passage it permits.|Keep it safe. Ask at Lilycove port.|I like having a clear place to start with a new possibility.|We can ask about the trip before deciding what to pack.|An invitation has arrived, with the next scene conveniently placed at the port.|A mystery ticket has at least supplied a perfectly ordinary address.|We should confirm the destination and requirements with the harbor staff.|A small piece of paper can open a surprisingly large path.|A ticket deserves a safe pocket until we know its plans for us.|I would ask the port attendant what we should know before using it.''')
add('check_group_restart','CableClub_Text_PleaseConfirmNumberAndRestart','An attendant asks players to confirm the group size and restart.','''soft_smile~Count the people, then start again. A small rehearsal for teamwork.|Verify the intended group size before repeating the connection.|Check the count first. Save a second failed attempt.|A quick check together should make the next try easier.|Everyone should know who is joining before we begin.|The opening has been sent back for a numerical revision.|The instructions request more counting and less hopeful button pressing.|One verified requirement should remove one source of failure.|A patient restart can be a better beginning.|A little adjustment should make the group fit the activity.|I would get a clear answer from everyone before trying again.''')
add('far_region_not_ready','CableClub_Text_NotSetUpForFarAwayRegion','A trade attendant explains that trades with trainers in a faraway region are not yet supported.','''sad~The distance has beaten the arrangements this time. We know why it stopped.|The available setup does not yet support that trade connection.|Cannot do that trade here yet. Good to know.|That is disappointing when someone was ready to meet.|We can keep the plan for when the service is ready.|The intended exchange has reached the present limits of the arrangement.|A polite apology from a service that has run out of reach.|The limitation is specific. Repeating the same attempt will not change it.|Some journeys wait for the path between them to be made.|A clear explanation is better than being left guessing at the refusal.|I would ask what arrangements are supported before planning another trade.''')
add('other_not_ready','CableClub_Text_OtherTrainerNotReady','A link attendant reports that the other trainer is not ready.','''soft_smile~The other trainer needs a moment. We can lend them that moment.|We should check their preparation before restarting the attempt.|Give them time. Ask if they need help.|I would hate to be the one everyone was rushing.|Being ready first does not make the other person late.|Our partner's opening cue has not arrived yet.|A delay is an excellent chance to stop pressing things hopefully.|A quick check with the other trainer should identify the missing step.|A shared activity begins more kindly when both people feel ready.|Patience suits this situation better than an impatient stare.|I would ask whether they can see the same screen we do.''')
add('link_goodbye','CableClub_Text_PleaseVisitAgain','A link attendant politely closes a canceled or aborted visit.','''soft_smile~A friendly goodbye after an uncompleted plan. We can come back prepared.|The visit ends, with the service still available for another attempt.|We can return later. No need to force it.|I like leaving with the welcome still there.|An unsuccessful attempt does not have to spoil the day.|Our postponed encounter concludes with impeccable professional courtesy.|The visit was brief. The invitation has a longer shelf life.|A later attempt gives us time to check the setup.|An unfinished plan can be left gently for another day.|A courteous farewell makes the inconvenience easier to leave behind.|I would return once everyone is ready for what we want to do.''')
add('restricted_partner','CableClub_Text_YouHaveAMonThatCantBeTaken','A link attendant refuses entry because at least one Pokemon cannot participate.','''soft_smile~Someone in the team cannot join this one. We should check the requirements.|We need to identify the participant restriction before trying again.|Check the team rules. Do not keep pushing the same entry.|I would rather understand the problem than leave someone out blindly.|A different arrangement may let everyone stay well looked after.|The invitation has encountered an exception in the guest list.|One of our companions has failed a rule nobody should have to guess.|We should compare the team's details with the actual entry criteria.|A closed door is easier to handle when we know why it closed.|Choose the arrangement carefully instead of treating a partner as the problem.|I would ask which restriction applies before changing the team.''')
add('record_versions','CableClub_Text_CantMixWithJapaneseGame','An attendant explains incompatible Japanese and overseas game combinations for record mixing.','''flustered~That is a very particular tangle of versions. We should check each one carefully.|The stated version combinations are incompatible. A different grouping is needed.|Check the versions. This combination will not mix records.|I am glad they explained it instead of just saying no.|Best make sure the group fits before everyone spends more time trying.|Our shared records have met a remarkably detailed border at the connection.|The meeting has been rejected by a very specific family tree of versions.|We can compare the exact combinations against the instructions.|A little clarity can keep a failed exchange from becoming an argument.|The right pairing matters more than repeating the attempt with confidence.|I would check each person's version before rearranging the group.''')

add('mom_registration','PlayersHouse_1F_Text_IsThatAPokenav','Mom asks to register in the players PokeNav; named registration receipt is ignored by root runtime patch.','''soft_smile~Mom found a way to keep in touch. Her first message is probably already smiling.|A direct way to stay in contact should be reassuring for both of them.|Good. She should be able to reach us.|That is a sweet way to ask to stay part of the journey.|Being away does not have to mean missing every small update.|The adventure has acquired its most personally invested correspondent.|Mother has successfully applied for a place in the contact list.|A useful connection, especially when the journey takes us farther away.|A familiar voice can make a distant place feel less far.|A little contact with home can fit almost anywhere.|I think she is happy to have a way to hear how we are doing.''')
add('birch_registration','MatchCall_Text_BirchRegisterCall','Birch registers for Match Call so he can examine the players Pokedex remotely; named receipt ignored by root patch.','''soft_smile~The professor can follow our discoveries without chasing us down the road.|Field observations are more useful when they can be reviewed promptly.|Good. We can keep him updated while traveling.|I like being able to share a new discovery while it is fresh.|A quick update can save everyone an unnecessary trip.|Our traveling discoveries have acquired a very eager remote reader.|The professor has found a practical alternative to appearing in every bush.|A direct link between the field record and the person studying it. Useful.|A little knowledge can travel back before our feet do.|A convenient way to keep the project connected while we keep moving.|I would like to know which discovery he asks us about first.''')

add('master_invitation','BerryBlender_Text_BlendWithTheBlendMaster','The Blend Master theatrically introduces himself and invites witnessing his skill.','''laughing~He is the Blend Master! I checked both announcements. They agree.|A confident claim. We can observe the timing for ourselves.|He sounds certain. Let the blending speak next.|That is an introduction nobody could mistake.|If the batch tastes half as good as the speech, we are in luck.|A masterful announcement of mastery, awaiting the minor detail of demonstration.|His title has been thoroughly confirmed by its owner.|I would be interested in watching the technique behind the reputation.|Confidence can make even a small blender seem grand.|That is a very bold way to present a specialty.|Now I want to see what he does differently from everyone else.''')
add('master_batch','BerryBlender_Text_MadeAmazingPokeblocksWithMaster','A participant recalls amazing Pokeblocks made while blending with the Master.','''soft_smile~The masterful berries apparently passed the taste test too.|A positive firsthand result gives the reputation some useful support.|They tried it and liked the result. Good sign.|They sound pleased to have been part of it.|That is the best kind of cooking boast: someone else enjoyed the batch.|A satisfied collaborator has supplied the review the Master would have requested.|The legend has survived its encounter with an actual snack.|I would like to compare the ingredients and timing of that batch.|A shared success can become a pleasant little memory.|A glowing result from someone who was actually there.|I would ask what made those Pokeblocks different from their usual ones.''')
add('master_precision','BerryBlender_Text_QualitiesOfBlendMaster','An admirer describes the Blend Masters intense tracking and precise button timing.','''surprised~Eyes on the arrow, finger exactly ready. His hands have excellent attendance.|Consistent timing requires attention and practiced coordination.|He pays attention and keeps the timing. That is work.|That kind of precision takes more practice than it looks.|A practiced hand can make a familiar task look extraordinary.|The legend has been translated into two rather demanding practical skills.|A whole reputation balanced on one exceptionally punctual finger.|Accurate sensing and precise control. That is a lovely combination.|Quiet attention can hide beneath a very grand title.|The polished result begins with details most people barely see.|I would watch his eyes as much as his hands.''')
add('master_mountains','BerryBlender_Text_MasterWorksOnSkillsInMountains','A fan says the Blend Master trains in the mountains and sometimes blends in Lilycove all day.','''laughing~A mountain retreat for elite berry whirling. The squirrels must be impressed.|Dedicated practice could explain his consistency, wherever it happens.|He takes the work seriously. Mountains or no mountains.|I can see the appeal of practicing somewhere quiet.|That is a long way to go to improve a batch of treats.|An ascetic training legend, brought gloriously down to earth by berries.|Some climb mountains for wisdom. He apparently seeks better mixing.|I wonder what part of the practice needs a whole mountain.|Solitude can give a small skill a surprising amount of room.|A dramatic routine for a very particular specialty.|I would love to ask him what he actually practices while he is away.''')
add('winstrate_son','Route111_WinstrateFamilysHouse_Text_MySonIsStrongerThanYou','Victor praises the players skill but boasts that his League-challenging son is stronger.','''laughing~A compliment with a son-shaped challenge hidden right behind it.|Our observed skill and his son's reputation have become separate comparisons.|Good to know. We can respect his son without arguing.|He managed to be impressed and proud of his son at once.|Family pride has a way of joining every conversation.|A glowing review, immediately followed by the family's preferred leading man.|Our compliment has been briefly detained by a very proud father.|I would be interested in what his son does differently in battle.|His pride in his son is the clearest part of the comparison.|A gracious opening with a little competitive family embroidery.|I would ask what match first made him realize his son was so strong.''')
add('winstrate_passion','Route111_WinstrateFamilysHouse_Text_PassionateAboutBattles','Victoria understatedly calls the Winstrate family passionate about battles.','''laughing~Pretty passionate is doing a lot of work for a whole family battle queue.|The family's enthusiasm is supported by a rather thorough demonstration.|We noticed. They put up a proper challenge.|That may be the quietest description of what just happened.|They clearly have something they love doing together.|A masterpiece of understatement from the household of consecutive challenges.|Passionate is one way to describe an entire family's coordinated ambush.|They have built a remarkably consistent family activity.|Shared enthusiasm can fill a small house quite completely.|They have a very distinct family style. No arguing with that.|I would love to see what an ordinary family practice looks like.''')
add('winstrate_rankings','Route111_WinstrateFamilysHouse_Text_StrongerFamilyMembers','Vivi ranks her whole familys strength from father through mother, herself, grandmother and brother.','''laughing~A family tree with battle rankings! Grandma is a very serious branch.|A complete comparative ranking, though we only have one observer's account.|Strong household. Hope the ranking stays friendly.|I wonder if everyone gives the same order when asked.|A competitive family still needs somewhere everyone can just have dinner.|Genealogy has been revised into a progressively more alarming challenge ladder.|Their family tree could apparently defeat most ordinary trees.|It would be interesting to compare each person's training method.|Every familiar face seems to carry another source of pride.|A rather formidable household, with Grandma well placed near the top.|I would ask how often that order changes after practice.''')
add('winstrate_grandson_long','Route111_WinstrateFamilysHouse_Text_GrandsonStrong','Vicky praises the player but predicts her grandson could already be Champion and make them cry.','''flustered~I was enjoying the compliment until it came with predicted crying.|Her confidence in her grandson is clear. His current result is still unknown.|Proud of him. We can leave the comparison unsettled.|I hope he knows how strongly she believes in him.|That is a lot of pride to send after someone traveling.|A proud grandmother has already drafted both his coronation and our defeat.|We have been assigned tears by someone else's family publicity office.|I would rather see the actual result than plan around a prediction.|Her grandson is far away, but her confidence keeps him very close.|A little less talk of our tears would improve the otherwise lovely pride.|I would ask when she last heard from him.''')
add('winstrate_grandson_short','Route111_WinstrateFamilysHouse_Text_GrandsonStrongShort','Vicky again imagines her grandson challenging or already becoming League Champion.','''soft_smile~She is cheering for him from all the way back here. Very powerful grandma energy.|She has a hopeful prediction, though a message from him would settle it.|She believes in him. Good thing to carry from home.|I wonder how he would smile if he heard her say that.|I hope she gets good news and a proper visit soon.|His absent adventure has a fiercely loyal audience at home.|The crown has already been fitted in his grandmother's imagination.|A progress update would be interesting after that confident forecast.|A distant journey can still have a warm place waiting behind it.|Family pride has given him a rather magnificent imagined ending.|I would love to see her face when he finally comes home.''')

add('base_wanderer','SecretBase_Text_Trainer0PreChampion','A base owner chose this spot after extensive searching and welcomes visitors.','''soft_smile~They searched everywhere and found somewhere to say make yourself comfortable.|Careful comparison seems to have led to a place they genuinely enjoy.|Good spot, friendly welcome. They chose well.|I like being invited to stay without having to be interesting.|A good place becomes better when the host makes room.|An extensive quest has concluded with a very welcoming little address.|All that wandering, and the treasure turned out to be somewhere to sit.|I would like to know which feature finally settled their choice.|A place can feel right long before we know how to explain it.|A well chosen little space with very inviting manners.|I would ask which other places almost won them over.''')
add('base_patient_owner','SecretBase_Text_Trainer1PreChampion','A base owner waited a long time for this popular location to become available.','''soft_smile~They finally got their favorite spot. That is a very patient kind of treasure hunt.|Their willingness to wait suggests the location matters quite a lot.|Worth the wait to them. Glad they got it.|I hope it feels as good as they imagined while waiting.|A long wait makes finally settling in feel special.|The coveted location has at last acquired its most persistent admirer.|Patience has been rewarded with a remarkably desirable hole in the landscape.|I would ask what makes this spot so consistently popular.|Waiting can make a familiar place feel newly precious.|Location matters, and this person certainly knew what they wanted.|I would love to hear what they planned while waiting for it.''')
add('base_company','SecretBase_Text_Trainer2PreChampion','A base owner prefers visitors here to living in a large mansion.','''soft_smile~A small base with lots of company beats a giant hallway saying echo.|The social experience matters more to them than the size of the building.|Good company makes a place. Fair choice.|A mansion could feel rather empty without people to share it.|A small table with willing guests is plenty.|The mansion has lost its contest with a lively little gathering place.|An enormous house is an expensive way to feel very far from the door.|A compact place can still serve a lot of different visitors.|A home can be measured by who feels welcome there.|A modest space with a rich social life sounds beautifully chosen.|I would ask what sort of visitors they enjoy meeting most.''')
add('base_hidden','SecretBase_Text_Trainer3PreChampion','A base owner wonders whether secluded locations mean their owners want quiet.','''soft_smile~Maybe they like visitors who have first defeated a small navigation puzzle.|Seclusion can offer privacy without implying an unwillingness to meet anyone.|Some people like quiet. Ask before wandering in.|I understand wanting somewhere that is a little hard to find.|A peaceful spot can make a visit feel like a proper break.|An obscure address may be a privacy preference or a personal challenge.|Some of us enjoy having neighbors at a geographically respectful distance.|Hard to find can mean fewer interruptions during a project.|A hidden place may simply give its owner room to breathe.|Privacy can be part of how someone chooses a place.|I would rather ask the owner than decide what the hiding means.''')
add('base_good_days','SecretBase_Text_Trainer4PreChampion','A base owner enjoys favorite decorations, a favorite Pokemon and steady growth.','''soft_smile~Favorite place, favorite stuff, favorite friend. A very strong good-day recipe.|A pleasing environment and a valued partner make a consistent routine easier.|They built a life they like. Good for them.|That sounds lovely in a very ordinary, attainable way.|A comfortable room and a happy partner can make a whole day.|A remarkably satisfying life assembled from a few well chosen favorites.|They have solved daily happiness without requiring a very large building.|A personalized workspace and a shared goal. Excellent starting conditions.|Some days grow good through small things tended well.|A place that fits your taste can make everything else sit better.|I would enjoy hearing which part they look forward to each morning.''')
add('base_favorite_spot','SecretBase_Text_Trainer5PreChampion','A base owner prefers this location despite the many other places available.','''soft_smile~So many possibilities, and this one felt right. The spot has a fan.|A favorite need not be the only suitable option to be a good choice.|They like it here. That is enough reason.|I like how pleased they sound when they show it.|The best place is often the one you actually enjoy coming back to.|The search is over, and the winning location receives a glowing introduction.|An entirely biased review from someone with excellent grounds for enjoying it.|I would ask which feature matters most to them.|A place becomes special through being chosen and returned to.|Taste is personal. Their confidence makes the place feel welcoming.|I would look for the detail that made them choose it.''')
add('base_secret_lab','SecretBase_Text_Trainer6PreChampion','A base owner welcomes the player to a secret laboratory for battle research.','''laughing~A secret lab with a welcome speech. The secrecy is feeling sociable today.|An informal research space can be useful, provided the observations are careful.|Keep the research safe for the partners involved.|I like a small quiet place to work on an idea.|Their partner should enjoy the routine as much as the researcher.|A confidential institution has issued an unexpectedly cordial press release.|The laboratory's secrecy has survived precisely until our arrival.|I would like to see what they record after each practice match.|A private place can give curiosity room to settle.|A laboratory with a very personal choice of surroundings.|I would ask which battle question they are working on now.''')
add('base_two_hobbies','SecretBase_Text_Trainer7PreChampion','A base owner equally enjoys shopping for decor and raising Pokemon.','''soft_smile~Decorating the base and raising friends. Hopefully the friends approve of the cushions.|Two different interests can make a nicely balanced routine.|Make the place comfortable for the Pokemon too.|It sounds like they enjoy making a life around both.|A well loved partner and a welcoming room go together nicely.|A host equally devoted to the residents and the scenery around them.|They have found two hobbies that both demand a surprising amount of floor space.|Furnishing a place is more interesting when you know who will use it.|A room can grow kinder as we learn the habits of those sharing it.|Finally, someone who understands the joy of choosing a good chair.|I would ask which piece of furniture their Pokemon likes best.''')
add('base_decor_race','SecretBase_Text_Trainer8PreChampion','A base owner proposes a friendly race to acquire nicer decorations and furniture.','''laughing~A furniture race! I hope the chairs are allowed to finish sitting down.|A friendly comparison could introduce us to different sources and styles.|Keep it friendly. A nicer chair is not worth a grudge.|I might prefer comparing the rooms after the rushing stops.|A good find is more fun when somebody else enjoys seeing it.|A domestic arms race has been declared, with cushions among the likely casualties.|Competition has found the last quiet corner and installed a display shelf.|We should define nicer before turning the shopping into a contest.|A room can please its owner without defeating another room.|A decor challenge sounds fun if personal taste still gets a vote.|I would like to see what each of us finds worth bringing home.''')
add('base_taste','SecretBase_Text_Trainer9PreChampion','A base owner says decor reveals peoples taste and teases a speechless visitor.','''flustered~I was observing! My opinion had not finished putting its little shoes on.|The arrangement does suggest preferences, though silence permits many interpretations.|Give us a moment to look before demanding a verdict.|I would rather offer a real thought than answer too quickly.|A room says a lot, especially about what makes someone comfortable.|Our thoughtful pause has been boldly mistaken for a standing ovation.|I am speechless in several possible directions. Let us be diplomatic.|I would look at how the objects work together, not just count them.|A chosen place can hold more of a person than they realize.|The display certainly starts a conversation. I would give it a proper look.|I would ask which piece they most wanted us to notice.''')
